     1|/**
     2| * IVX Completion Validator
     3| *
     4| * Final, deterministic gate before IVX can claim a task is COMPLETE, VERIFIED,
     5| * or DEPLOYED. It compares the owner-requested outcome against the actual
     6| * evidence captured during execution. This prevents the false-completion
     7| * pattern where a deploy-only redeploy or a health check is reported as a
     8| * fixed defect.
     9| *
    10| * Rules (owner mandate 2026-07-20):
    11| *   - DEPLOYED means a deployment occurred; it does NOT mean a defect is fixed.
    12| *   - VERIFIED means the requested acceptance tests passed.
    13| *   - A CODE_FIX/UI_FIX/FEATURE task cannot be VERIFIED when no code changed
    14| *     unless the root cause was genuinely external (config/data/infra).
    15| *   - If no work was completed, status must be NO_CHANGE_REQUIRED, BLOCKED,
    16| *     or FAILED — never "DEPLOYED" or "COMPLETE".
    17| *   - Never display "development completed" when the code diff is empty.
    18| *
    19| * This module is intentionally runtime-free and does NOT import worker types,
    20| * to avoid circular dependencies with ivx-senior-developer-worker.
    21| */
    22|
    23|export const IVX_COMPLETION_VALIDATOR_MARKER = 'ivx-completion-validator-2026-07-20';
    24|
    25|export type IVXTaskType =
    26|  | 'CODE_FIX'
    27|  | 'FEATURE'
    28|  | 'UI_FIX'
    29|  | 'DATA_FIX'
    30|  | 'CONFIGURATION_FIX'
    31|  | 'INFRASTRUCTURE_FIX'
    32|  | 'DEPLOYMENT'
    33|  | 'QA_ONLY'
    34|  | 'INVESTIGATION'
    35|  | 'CONTENT_REQUEST'
    36|  | 'BUSINESS_ANALYSIS';
    37|
    38|export type IVXTaskState =
    39|  | 'RECEIVED'
    40|  | 'ANALYZING'
    41|  | 'REPRODUCING'
    42|  | 'ROOT_CAUSE_IDENTIFIED'
    43|  | 'IMPLEMENTING'
    44|  | 'CODE_CHANGED'
    45|  | 'TESTING'
    46|  | 'QA_REQUIRED'
    47|  | 'QA_IN_PROGRESS'
    48|  | 'READY_TO_DEPLOY'
    49|  | 'DEPLOYING'
    50|  | 'DEPLOYED'
    51|  | 'PRODUCTION_VERIFYING'
    52|  | 'VERIFIED'
    53|  | 'BLOCKED'
    54|  | 'FAILED'
    55|  | 'NO_CHANGE_REQUIRED';
