   111|export function classifyTaskType(goal: string): IVXTaskType {
   112|  const normalized = (goal ?? '').toLowerCase();
   113|  if (/(audit|inspect|investigate|trace|root cause|diagnose|find why|report)/i.test(normalized)
   114|      && !/(fix|deploy|change|edit|apply|implement|patch|build|upgrade|create)/i.test(normalized)) {
   115|    return 'INVESTIGATION';
   116|  }
   117|  if (/\b(deploy|redeploy|push live|release|rollout|render deploy)\b/i.test(normalized)
   118|      && !/(fix|bug|patch|feature|implement|ui|scroll|loading|chat|screen)/i.test(normalized)) {
   119|    return 'DEPLOYMENT';
   120|  }
   121|  if (/(qa|test|verify|acceptance|regression|check|validate|measure)/i.test(normalized)
   122|      && !/(fix|deploy|change|edit|apply|implement|patch|build|upgrade)/i.test(normalized)) {
   123|    return 'QA_ONLY';
   124|  }
   125|  if (/(configuration|config|env|environment variable|render env|setting|toggle)/i.test(normalized)) {
   126|    return 'CONFIGURATION_FIX';
   127|  }
   128|  if (/(infrastructure|server|database|redis|queue|render service|supabase project|migrate schema)/i.test(normalized)) {
   129|    return 'INFRASTRUCTURE_FIX';
   130|  }
   131|  if (/(data fix|clean data|delete test|fix data|sanitize data|merge records|deduplicate)/i.test(normalized)) {
   132|    return 'DATA_FIX';
   133|  }
   134|  if (/(content|copy|text|wording|label|title|placeholder|typo|document|pdf|attachment)/i.test(normalized)) {
   135|    return 'CONTENT_REQUEST';
   136|  }
   137|  if (/(business model|pricing|roi|investor|deal structure|capital|workflow|process|kpi|metric)/i.test(normalized)) {
   138|    return 'BUSINESS_ANALYSIS';
   139|  }
   140|  if (/(ui|interface|screen|component|button|modal|scroll|loading|keyboard|composer|chat|flatlist|scrollview|view|color|theme|style|layout|icon|animation)/i.test(normalized)) {
   141|    return 'UI_FIX';
   142|  }
   143|  if (/(fix|bug|repair|correct|resolve|patch|issue|error|crash|exception|broken|not working|failed|slow|timeout|stuck|hang|leak|race|deadlock)/i.test(normalized)) {
   144|    return 'CODE_FIX';
   145|  }
   146|  if (/(feature|implement|add|build|create|introduce|support|enable|new capability|new module|new app|new screen)/i.test(normalized)) {
   147|    return 'FEATURE';
   148|  }
   149|  return 'INVESTIGATION';
