   152|export function validateCompletion(
   153|  evidence: IVXCompletionEvidence,
   154|): IVXCompletionValidationResult {
   155|  const reasons: string[] = [];
   156|
   157|  if (evidence.previousVerdict === 'VERIFIED' && !evidence.featureVerificationOk) {
   158|    reasons.push('Previous VERIFIED claim has no feature-verification evidence');
   159|  }
   160|  if (evidence.verifiedAt && evidence.completedAt && evidence.verifiedAt < evidence.completedAt) {
   161|    reasons.push('Verification timestamp predates task completion');
   162|  }
   163|
   164|  const isDevelopment = DEVELOPMENT_TASK_TYPES.has(evidence.taskType);
   165|  const isDeployment = DEPLOYMENT_TASK_TYPES.has(evidence.taskType);
   166|
   167|  // A development task with no code change cannot be VERIFIED or DEPLOYED as a fix.
   168|  if (isDevelopment && evidence.filesChanged.length === 0) {
   169|    if (evidence.deployId && evidence.productionHealthOk && evidence.commitMatch) {
   170|      reasons.push('Development task requested but no code changed; redeploy is not a fix');
   171|      return {
   172|        ok: false,
   173|        verdict: 'DEPLOYED_ONLY',
   174|        state: 'DEPLOYED',
   175|        reasons,
   176|        evidence,
   177|        marker: IVX_COMPLETION_VALIDATOR_MARKER,
   178|      };
   179|    }
   180|    reasons.push('Development task requested but no code changed and no deployment proof');
   181|    return {
   182|      ok: false,
   183|      verdict: 'NOT_COMPLETED',
   184|      state: 'NO_CHANGE_REQUIRED',
   185|      reasons,
   186|      evidence,
   187|      marker: IVX_COMPLETION_VALIDATOR_MARKER,
   188|    };
   189|  }
   190|
   191|  // Deployment-only task with a redeploy and health OK -> VERIFIED only if infra/config was the actual cause.
   192|  if (isDeployment && evidence.filesChanged.length === 0) {
   193|    if (evidence.deployId && evidence.productionHealthOk && evidence.commitMatch) {
   194|      return {
   195|        ok: true,
   196|        verdict: 'VERIFIED',
   197|        state: 'VERIFIED',
   198|        reasons: ['Deployment-only task completed with a live redeploy and health confirmation'],
   199|        evidence,
   200|        marker: IVX_COMPLETION_VALIDATOR_MARKER,
   201|      };
   202|    }
   203|    return {
   204|      ok: false,
   205|      verdict: 'NOT_COMPLETED',
   206|      state: 'NO_CHANGE_REQUIRED',
   207|      reasons: ['Deployment-only task but no live deployment proof'],
   208|      evidence,
   209|      marker: IVX_COMPLETION_VALIDATOR_MARKER,
   210|    };
   211|  }
   212|
   213|  // QA-only task needs actual test results.
   214|  if (evidence.taskType === 'QA_ONLY') {
   215|    if (evidence.testsRun && evidence.testsPassed) {
   216|      return {
   217|        ok: true,
   218|        verdict: 'VERIFIED',
   219|        state: 'VERIFIED',
   220|        reasons: ['QA-only task completed with passing tests'],
   221|        evidence,
   222|        marker: IVX_COMPLETION_VALIDATOR_MARKER,
   223|      };
   224|    }
   225|    return {
   226|      ok: false,
   227|      verdict: 'NOT_COMPLETED',
   228|      state: 'QA_REQUIRED',
   229|      reasons: ['QA-only task but no tests were run or tests failed'],
   230|      evidence,
   231|      marker: IVX_COMPLETION_VALIDATOR_MARKER,
   232|    };
   233|  }
   234|
   235|  // Investigation/read-only task does not require code changes.
   236|  if (evidence.taskType === 'INVESTIGATION') {
   237|    return {
   238|      ok: true,
   239|      verdict: 'VERIFIED',
   240|      state: 'VERIFIED',
   241|      reasons: ['Investigation task completed; no code change required'],
   242|      evidence,
   243|      marker: IVX_COMPLETION_VALIDATOR_MARKER,
   244|    };
   245|  }
   246|
   247|  // Content/business analysis tasks do not require deployment.
   248|  if (evidence.taskType === 'CONTENT_REQUEST' || evidence.taskType === 'BUSINESS_ANALYSIS') {
   249|    if (evidence.filesChanged.length > 0 || evidence.testsPassed) {
   250|      return {
   251|        ok: true,
   252|        verdict: 'VERIFIED',
   253|        state: 'VERIFIED',
   254|        reasons: ['Task completed with required evidence'],
   255|        evidence,
   256|        marker: IVX_COMPLETION_VALIDATOR_MARKER,
   257|      };
   258|    }
   259|    return {
   260|      ok: false,
   261|      verdict: 'NOT_COMPLETED',
   262|      state: 'NO_CHANGE_REQUIRED',
   263|      reasons: ['No deliverable or evidence produced for this task type'],
   264|      evidence,
   265|      marker: IVX_COMPLETION_VALIDATOR_MARKER,
   266|    };
   267|  }
   268|
   269|  // General development task with real code change and deployed+health OK -> VERIFIED.
   270|  if (evidence.filesChanged.length > 0) {
   271|    if (!evidence.testsRun) {
   272|      reasons.push('Files changed but tests were not run');
   273|    } else if (!evidence.testsPassed) {
   274|      reasons.push('Files changed but tests failed');
   275|    }
   276|    if (!evidence.deployId) {
   277|      reasons.push('Files changed but no deployment occurred');
   278|    }
   279|    if (!evidence.productionHealthOk) {
   280|      reasons.push('Files changed but production health is not confirmed');
   281|    }
   282|    if (!evidence.commitMatch) {
   283|      reasons.push('Files changed but production commit does not match the deployed commit');
   284|    }
   285|    if (reasons.length > 0) {
   286|      return {
   287|        ok: false,
   288|        verdict: 'NOT_COMPLETED',
   289|        state: evidence.deployId ? 'PRODUCTION_VERIFYING' : 'READY_TO_DEPLOY',
   290|        reasons,
   291|        evidence,
   292|        marker: IVX_COMPLETION_VALIDATOR_MARKER,
   293|      };
   294|    }
   295|    return {
   296|      ok: true,
   297|      verdict: 'VERIFIED',
   298|      state: 'VERIFIED',
   299|      reasons: ['Code changed, tested, deployed, and production health/commit verified'],
   300|      evidence,
   301|      marker: IVX_COMPLETION_VALIDATOR_MARKER,
   302|    };
   303|  }
   304|
   305|  // Fallback: nothing meaningful happened.
   306|  reasons.push('No code changed, no deployment, and no task-specific evidence produced');
   307|  return {
   308|    ok: false,
   309|    verdict: 'NOT_COMPLETED',
   310|    state: 'NO_CHANGE_REQUIRED',
   311|    reasons,
   312|    evidence,
   313|    marker: IVX_COMPLETION_VALIDATOR_MARKER,
   314|  };
   315|}
   316|
   317|export function renderValidatorVerdict(verdict: IVXValidationVerdict): string {
   318|  switch (verdict) {
   319|    case 'VERIFIED':
   320|      return 'VERIFIED';
   321|    case 'DEPLOYED_ONLY':
   322|      return 'DEPLOYED_ONLY';
   323|    case 'NO_CHANGE_REQUIRED':
   324|      return 'NO_CHANGE_REQUIRED';
   325|    case 'BLOCKED':
   326|      return 'BLOCKED';
   327|    case 'FAILED':
   328|      return 'FAILED';
   329|    case 'NOT_COMPLETED':
   330|    default:
   331|      return 'NOT_COMPLETED';
   332|  }
   333|}
   334|
   335|export function renderValidatorReason(verdict: IVXValidationVerdict, reasons: string[]): string {
   336|  switch (verdict) {
   337|    case 'VERIFIED':
   338|      return reasons[0] ?? 'Validation accepted.';
   339|    case 'DEPLOYED_ONLY':
   340|      return 'A redeploy occurred, but no code changed. The requested fix/feature was NOT implemented.';
   341|    case 'NO_CHANGE_REQUIRED':
   342|      return reasons[0] ?? 'No code change was required and no deployment was requested.';
   343|    case 'BLOCKED':
   344|      return reasons[0] ?? 'Blocked before execution.';
   345|    case 'FAILED':
   346|      return reasons[0] ?? 'Execution failed.';
   347|    case 'NOT_COMPLETED':
   348|    default:
   349|      return reasons.join('; ') || 'Task not completed.';
   350|  }
