  1167|async function listOwnerMessages(): Promise<IVXMessage[]> {
  1168|  const localMessages = await loadLocalMessages();
  1169|  if (isIVXLocalFirstChatEnabled()) {
  1170|    console.log('[IVXChatService] Local-first mode active; listing local owner messages:', localMessages.length);
  1171|    return localMessages;
  1172|  }
  1173|
  1174|  const client = getIVXSupabaseClient();
  1175|  const tables = await resolveIVXTables();
  1176|  const scopedClient = getScopedSupabaseClient(client, tables.dbSchema);
  1177|  const conversation = await bootstrapOwnerConversation();
  1178|  const messageConversationField = tables.schema === 'generic' ? 'room_id' : 'conversation_id';
  1179|
  1180|  if (tables.schema === 'none') {
  1181|    console.log('[IVXChatService] No IVX tables available, listing local owner messages');
  1182|    return localMessages;
  1183|  }
  1184|
  1185|  // OPEN-ON-LATEST BOUNDED LOAD (2026-07-19): fetch the most recent N messages
  1186|  // newest-first from the DB, then reverse in-memory for chronological display.
  1187|  // Previously this query had NO LIMIT and ordered ascending, so a months-old
  1188|  // conversation with hundreds of turns forced the FlatList to lay out every
  1189|  // message before scroll-to-latest could work — the scroll retry gave up
  1190|  // after ~1.5s and the owner was left looking at months-old messages. Bounding
  1191|  // the initial load to the recent tail makes the latest turn visible in
  1192|  // <200ms. Older history remains accessible via the durable local mirror
  1193|  // (capped at IVX_LOCAL_MESSAGES_MIRROR_CAP=400) which is merged below.
  1194|  const INITIAL_PAGE_LIMIT = 120;
  1195|  console.log('[IVXChatService] Listing messages from:', tables.messages, 'conversation:', conversation.id, 'dbSchema:', tables.dbSchema, 'localFallbackCount:', localMessages.length, 'messageConversationField:', messageConversationField, 'initialPageLimit:', INITIAL_PAGE_LIMIT);
  1196|  const messageResult = await scopedClient.from(tables.messages).select('*').eq(messageConversationField, conversation.id).order('created_at', { ascending: false }).limit(INITIAL_PAGE_LIMIT);
  1197|
  1198|  if (messageResult.error) {
  1199|    console.log('[IVXChatService] Failed to list messages, falling back to local cache:', messageResult.error.message);
  1200|    return localMessages;
  1201|  }
  1202|
  1203|  // Reverse the newest-first rows back to chronological (oldest→newest) order
  1204|  // so the rendered thread reads top-to-bottom and the FlatList's last item is
  1205|  // the latest message — which is what scroll-to-latest and initialScrollIndex
  1206|  // target.
  1207|  const rawRows = (messageResult.data ?? []) as Record<string, unknown>[];
  1208|  const chronologicalRows = [...rawRows].reverse();
  1209|  let remoteMessages = await Promise.all(chronologicalRows.map((row) => mapMessage(row)));
  1210|
  1211|  // DISAPPEAR-FIX (2026-07-05): when the primary conversation-id query returns
  1212|  // empty but the durable local mirror has messages, the canonical conversation
  1213|  // id has diverged from the id the messages were saved under. Recover by
  1214|  // querying recent messages across ALL conversations (capped) and merging with
  1215|  // the local mirror, so the owner never sees an empty room over a saved thread.
  1216|  if (remoteMessages.length === 0 && localMessages.length > 0) {
  1217|    console.log('[IVXChatService] Primary conversation returned 0 remote messages but local mirror has', localMessages.length, '- attempting cross-conversation recovery');
  1218|    try {
  1219|      const recoveryResult = await scopedClient.from(tables.messages)
  1220|        .select('*')
  1221|        .order('created_at', { ascending: true })
  1222|        .limit(200);
  1223|      if (!recoveryResult.error && recoveryResult.data && recoveryResult.data.length > 0) {
  1224|        const recoveredRemote = await Promise.all(recoveryResult.data.map((row) => mapMessage(row as Record<string, unknown>)));
  1225|        // Only keep messages whose signature matches one in the local mirror —
  1226|        // this is the owner's own thread, recovered from wherever it was saved.
  1227|        const localSignatures = new Set(localMessages.map((m) =>
  1228|          [String(m.conversationId ?? '').trim().toLowerCase(),
  1229|           String(m.senderRole ?? '').trim().toLowerCase(),
  1230|           String(m.body ?? '').trim().toLowerCase()].join('::')
  1231|        ));
  1232|        const matchedRecovered = recoveredRemote.filter((m) => {
  1233|          const sig = [String(m.conversationId ?? '').trim().toLowerCase(),
  1234|                       String(m.senderRole ?? '').trim().toLowerCase(),
  1235|                       String(m.body ?? '').trim().toLowerCase()].join('::');
  1236|          return localSignatures.has(sig);
  1237|        });
  1238|        if (matchedRecovered.length > 0) {
  1239|          console.log('[IVXChatService] Cross-conversation recovery matched', matchedRecovered.length, 'of', recoveredRemote.length, 'recent remote messages');
  1240|          remoteMessages = matchedRecovered;
  1241|        }
  1242|      }
