import { readFileSync } from 'node:fs';
import { gzipSync } from 'node:zlib';
const TOKEN = readFileSync('/tmp/owner_at', 'utf8').trim();
const file = 'expo/src/modules/ivx-owner-ai/services/ivxChatMessageMerge.ts';
const content = readFileSync(file);
const b64 = gzipSync(content).toString('base64');
const payload = JSON.stringify({
  action: 'github_commit_file',
  input: { path: file, content: b64, contentEncoding: 'gzip-base64', message: 'IVX 16-phase rebuild Phase 4D: stable message ordering with id tiebreak (prevents equal-timestamp reorder after realtime sync)' },
  confirm: true,
  confirmText: 'CONFIRM_IVX_GITHUB_WRITE',
});
const res = await fetch('https://api.ivxholding.com/api/ivx/developer-deploy/action', {
  method: 'POST',
  headers: { 'Authorization': `Bearer ${TOKEN}`, 'Content-Type': 'application/json' },
  body: payload,
});
const d = await res.json();
const r = d.result ?? d;
const sha = r.commitSha ?? r.sha ?? '';
console.log('ok=' + (r.ok ?? (sha && sha.length > 0)) + ' sha=' + String(sha).slice(0,12));
EOF
node /tmp/commit_chat_fix.mjs 2>&1 | tail -3

